import { RuleEngine, type Rule } from 'ts-rule-engine'
interface Order { units: number; discount: number }
const volumeDiscount: Rule<Order> = {
  id: 'volume-discount',
  name: 'Volume discount',
  weight: 10,
  condition: (order) => order.units > 100,
  action: (order, { stop }) => { order.discount = 0.10; stop() }
}
const engine = new RuleEngine<Order>({ units: 250, discount: 0 })
engine.addRule(volumeDiscount)
await engine.run()

