import { Engine } from 'json-rules-engine'

interface Facts { units: number; loyaltyYears: number }

const engine = new Engine([{
  conditions: { all: [
    { fact: 'units', operator: 'greaterThan', value: 100 },
    { fact: 'loyaltyYears', operator: 'greaterThan', value: 2 }
  ]},
  event: { type: 'volume-discount', params: { rate: 0.10 } }
}])

const { events } = await engine.run(facts satisfies Facts)
